from flask import Flask, render_template, jsonify
import pandas as pd, os
app=Flask(__name__)
DATA_DIR=os.path.join(os.path.dirname(__file__),'data')
def load_data():
    for f in os.listdir(DATA_DIR):
        if f.endswith('.csv'):
            return pd.read_csv(os.path.join(DATA_DIR,f))
        if f.endswith('.xlsx'):
            return pd.read_excel(os.path.join(DATA_DIR,f))
    return pd.DataFrame()
DATA=load_data()
@app.route('/')
def index():
    return render_template('index.html')
@app.route('/api/sales_trend')
def sales_trend():
    df=DATA.copy()
    df['date']=pd.to_datetime(df['date'])
    daily=df.groupby(df['date'].dt.date)['price'].sum().reset_index()
    return jsonify({'labels':[str(d) for d in daily['date']],'values':daily['price'].tolist()})
@app.route('/api/top_dishes')
def top_dishes():
    df=DATA.copy()
    top=df.groupby('item')['price'].sum().nlargest(5).reset_index()
    return jsonify({'labels':top['item'].tolist(),'values':top['price'].tolist()})
@app.route('/api/revenue_category')
def revenue_category():
    df=DATA.copy()
    cat=df.groupby('category')['price'].sum().reset_index()
    return jsonify({'labels':cat['category'].tolist(),'values':cat['price'].tolist()})
if __name__=='__main__':
    app.run(debug=True)

/* Warm light theme for Indian Restaurant dashboard */

/* Import Google Font */
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600&display=swap');

:root {
  --primary: #ff8c00; /* saffron orange */
  --secondary: #f5c242; /* amber */
  --bg: #fffdf5; /* very light cream */
  --text: #2c1b0c; /* deep brown */
  --card-bg: rgba(255, 255, 255, 0.9);
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Poppins', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  padding: 1rem;
}

header {
  text-align: center;
  margin-bottom: 2rem;
}

h1 {
  font-size: 2.5rem;
  color: var(--primary);
  font-weight: 600;
}

main {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 1.5rem;
}

.chart-card {
  background: var(--card-bg);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: var(--shadow);
  transition: transform 0.2s ease;
}

.chart-card:hover {
  transform: translateY(-4px);
}

.chart-card h2 {
  margin-bottom: 1rem;
  font-size: 1.4rem;
  color: var(--secondary);
  text-align: center;
}

canvas {
  max-width: 100%;
  height: auto;
}

@media (max-width: 600px) {
  h1 { font-size: 2rem; }
  .chart-card h2 { font-size: 1.2rem; }
}

// charts.js – fetch data from Flask API and render with Chart.js

async function fetchChartData(endpoint) {
  const response = await fetch(endpoint);
  if (!response.ok) throw new Error('Network response was not ok');
  return response.json();
}

function renderLineChart(ctx, labels, data) {
  new Chart(ctx, {
    type: 'line',
    data: {
      labels: labels,
      datasets: [{
        label: 'Daily Sales',
        data: data,
        borderColor: 'var(--primary)',
        backgroundColor: 'rgba(255,140,0,0.2)',
        fill: true,
        tension: 0.3
      }]
    },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: { y: { beginAtZero: true } }
    }
  });
}

function renderBarChart(ctx, labels, data) {
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [{
        label: 'Top Dishes',
        data: data,
        backgroundColor: 'var(--secondary)',
        borderColor: 'var(--primary)',
        borderWidth: 1
      }]
    },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: { y: { beginAtZero: true } }
    }
  });
}

function renderPieChart(ctx, labels, data) {
  new Chart(ctx, {
    type: 'pie',
    data: {
      labels: labels,
      datasets: [{
        data: data,
        backgroundColor: [
          'var(--primary)',
          'var(--secondary)',
          '#d4a373',
          '#8c6239',
          '#f2e2c4'
        ]
      }]
    },
    options: { responsive: true }
  });
}

(async () => {
  try {
    // Sales Trend
    const sales = await fetchChartData('/api/sales_trend');
    renderLineChart(document.getElementById('salesTrendChart'), sales.labels, sales.values);

    // Top Dishes
    const top = await fetchChartData('/api/top_dishes');
    renderBarChart(document.getElementById('topDishesChart'), top.labels, top.values);

    // Revenue by Category
    const cat = await fetchChartData('/api/revenue_category');
    renderPieChart(document.getElementById('revenueCategoryChart'), cat.labels, cat.values);
  } catch (e) {
    console.error('Error loading charts:', e);
  }
})();

/* Chatbot UI – simple fixed‑position widget */

.chatbot-toggle {
  position: fixed;
  bottom: 20px;
  right: 20px;
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 50%;
  width: 56px;
  height: 56px;
  font-size: 24px;
